from collections import deque

# Parse the edges from context
edges_text = context.split("The graph has the following edges:")[1].split("Operation:")[0].strip()

# Build adjacency list
graph = {}
for line in edges_text.strip().split('\n'):
    line = line.strip()
    if '->' in line:
        parts = line.split('->')
        src = parts[0].strip()
        dst = parts[1].strip()
        if src not in graph:
            graph[src] = []
        graph[src].append(dst)

print("Adjacency list:")
for k, v in sorted(graph.items()):
    print(f"{k}: {v}")

print("\nStarting BFS from 8f14e45fce")

# BFS from 8f14e45fce, find nodes at exactly depth 4
start = "8f14e45fce"
queue = deque([(start, 0)])  # (node, depth)
visited = {start}
depth_nodes = {0: [start]}

while queue:
    node, depth = queue.popleft()
    if depth >= 4:
        continue
    if node in graph:
        for neighbor in graph[node]:
            # For BFS we track depth levels, but we need to be careful about cycles
            # We want to track all nodes at each depth level
            new_depth = depth + 1
            if new_depth not in depth_nodes:
                depth_nodes[new_depth] = []
            if neighbor not in depth_nodes[new_depth]:
                depth_nodes[new_depth].append(neighbor)
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, new_depth))

print(f"\nNodes at depth 4: {sorted(depth_nodes.get(4, []))}")
```

